import { PlaneGeometry, MeshBasicNodeMaterial, TextureLoader, Group } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.cleanup = () => {
    // Placeholder for resources that will be created
  };

  const imageUrl = config.assets.imageUrl;
  if (!imageUrl) {
    console.warn('Pricing card label: no imageUrl provided');
    return group;
  }

  // Load texture using context texture loader
  const texLoader = ctx.textureLoader;
  const mapTexture = texLoader.load(imageUrl);

  // Calculate plane dimensions based on texture aspect ratio
  const image = new Image();
  image.src = imageUrl;
  const naturalWidth = image.naturalWidth || 512;
  const naturalHeight = image.naturalHeight || 320;
  const aspect = naturalWidth / naturalHeight;
  const planeWidth = 1.5;
  const planeHeight = planeWidth / aspect;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    map: mapTexture,
    side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.scenePlacement.position.x, config.scenePlacement.position.y, config.scenePlacement.position.z);
  mesh.rotation.set(config.scenePlacement.rotation.x, config.scenePlacement.rotation.y, config.scenePlacement.rotation.z);
  mesh.scale.set(config.scenePlacement.scale.x, config.scenePlacement.scale.y, config.scenePlacement.scale.z);
  group.add(mesh);

  // Render text content if provided
  if (config.textContent && config.textContent.length > 0) {
    // Assume first text entry is the headline
    const textEntry = config.textContent[0];
    const fontSize = 0.34; // scene units for headline from type scale
    const textMesh = ctx.fontAtlas.createText(textEntry.text, {
      fontSize: 0.34,
      fontFamily: 'Lora',
      fontWeight: 400,
      color: '#16161d', // ink color
      align: 'center',
      baseline: 'center',
    });
    // Position text in front of the plane slightly
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
    // Store for cleanup
    group.userData._textMesh = textMesh;
  }

  // No cinematic primitives to apply

  // Event handlers (none)
  group.userData.handlers = {};

  // Cleanup function
  const originalCleanup = group.userData.cleanup;
  group.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    mapTexture.dispose();
    if (group.userData._textMesh) {
      group.userData._textMesh.material.dispose();
      group.userData._textMesh.geometry.dispose();
    }
    // No GSAP timelines to kill
    originalCleanup();
  };

  return group;
}
